def coincide(titulo_doc, titulo_esperado):
    return titulo_esperado.lower() in titulo_doc.lower()


def evaluar():
    index, docs, chunk_a_doc = cargar_index()

    total_precision = 0
    total_recall = 0

    for caso in CASOS_DE_PRUEBA:
        pregunta = caso["pregunta"]
        esperados = caso["titulos_esperados"]

        encontrados = buscar_documentos(pregunta, index, docs, chunk_a_doc, prev_docs=[])
        titulos_encontrados = [d.get("title", "") for d in encontrados]

        aciertos = 0
        for esperado in esperados:
            if any(coincide(t, esperado) for t in titulos_encontrados):
                aciertos += 1

        precision = aciertos / len(titulos_encontrados) if titulos_encontrados else 0
        recall = aciertos / len(esperados) if esperados else 0

        total_precision += precision
        total_recall += recall

        print(f"\nPregunta: {pregunta}")
        print(f"  Esperados: {esperados}")
        print(f"  Encontrados ({len(titulos_encontrados)}): {titulos_encontrados[:5]}...")
        print(f"  Precision: {precision:.2f} | Recall: {recall:.2f}")

    n = len(CASOS_DE_PRUEBA)
    print(f"\n=== RESULTADOS GLOBALES ({n} casos) ===")
    print(f"Precision media: {total_precision / n:.2f}")
    print(f"Recall media: {total_recall / n:.2f}")


if __name__ == "__main__":
    evaluar()